draw:
var xs = [1,2,3,4,5];
var ys = [2.1,3.9,6.2,7.9,10.1];
var m = p.slope, b = p.intercept;
var pad = 38;
var X = function(x){ return pad + (x/6) * (W - pad - 14); };
var Y = function(y){ return H - pad - (y/12) * (H - pad - 14); };

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(6), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(12)); ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.figure;
ctx.fillText("x", X(5.8), Y(0) + 16);
ctx.fillText("y", X(0) - 22, Y(11.4));
ctx.strokeStyle = C.faint;
var gi;
for (gi = 2; gi <= 10; gi += 2) {
  ctx.beginPath(); ctx.moveTo(X(0), Y(gi)); ctx.lineTo(X(6), Y(gi)); ctx.stroke();
  ctx.fillText(String(gi), X(0) - 20, Y(gi) + 4);
}
for (gi = 1; gi <= 5; gi += 1) {
  ctx.fillText(String(gi), X(gi) - 3, Y(0) + 16);
}

// trial line
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(X(0), Y(b)); ctx.lineTo(X(6), Y(m * 6 + b)); ctx.stroke();

// residuals
var ssr = 0, i, fit, r;
ctx.lineWidth = 4;
ctx.strokeStyle = C.figure;
for (i = 0; i < xs.length; i++) {
  fit = m * xs[i] + b;
  r = ys[i] - fit;
  ssr += r * r;
  ctx.beginPath();
  ctx.moveTo(X(xs[i]), Y(fit));
  ctx.lineTo(X(xs[i]), Y(ys[i]));
  ctx.stroke();
}

// points
ctx.fillStyle = C.ink;
for (i = 0; i < xs.length; i++) {
  ctx.beginPath(); ctx.arc(X(xs[i]), Y(ys[i]), 4, 0, Math.PI * 2); ctx.fill();
}

ctx.fillStyle = C.figure;
ctx.fillText("thick bars are the residuals", X(0.3), Y(11.2));
ctx.fillText("best fit: slope 2.00, intercept 0.04, sum 0.072", X(0.3), Y(10.2));

out.note = "sum of squared residuals = " + ssr.toFixed(3) + (ssr < 0.0725 ? "  (this is the least-squares line)" : "  (drag closer to the minimum)");

var tau = p.tau, mode = p.mode;
var ts = [0, 10, 20, 30, 40, 50];
var pad = 42;
var i, v;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

var A = function(tt){ return 100 * Math.exp(-tt / tau); };

var yMax = mode < 0.5 ? 110 : 5.2;
var yMin = mode < 0.5 ? 0 : 0;
var X = function(x){ return pad + (x / 55) * (W - pad - 16); };
var Y = function(y){ return H - pad - ((y - yMin) / (yMax - yMin)) * (H - pad - 18); };

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(X(0), Y(yMin)); ctx.lineTo(X(55), Y(yMin)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(0), Y(yMin)); ctx.lineTo(X(0), Y(yMax)); ctx.stroke();

ctx.fillStyle = C.figure;
ctx.fillText("t (s)", X(48), Y(yMin) + 16);
ctx.fillText(mode < 0.5 ? "A (mm)" : "ln A", X(0) - 30, Y(yMax) - 4);
for (i = 0; i <= 50; i += 10) { ctx.fillText(String(i), X(i) - 6, Y(yMin) + 16); }

// smooth model curve
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath();
for (i = 0; i <= 110; i++) {
  var tt = i * 0.5;
  v = mode < 0.5 ? A(tt) : Math.log(A(tt));
  if (i === 0) ctx.moveTo(X(tt), Y(v)); else ctx.lineTo(X(tt), Y(v));
}
ctx.stroke();
ctx.setLineDash([]);

// data points appear one by one
var shown = 1 + Math.floor((t % 6) );
if (shown > ts.length) shown = ts.length;
ctx.fillStyle = C.accent;
for (i = 0; i < shown; i++) {
  v = mode < 0.5 ? A(ts[i]) : Math.log(A(ts[i]));
  ctx.beginPath(); ctx.arc(X(ts[i]), Y(v), 4.5, 0, Math.PI * 2); ctx.fill();
}

ctx.fillStyle = C.ink;
ctx.fillText(mode < 0.5 ? "A against t: a curve, no slope to read" : "ln A against t: a straight line of slope -1/tau",
             X(3), Y(yMax) - 4);

out.note = mode < 0.5
  ? "tau = " + tau.toFixed(0) + " s. Curved. Push the axis slider to 1 to take logs."
  : "tau = " + tau.toFixed(0) + " s, slope = -1/tau = " + (-1 / tau).toFixed(4) + " per s";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var parts = [
  { name: "F  (1 x 1.0%)", v: 1.0 },
  { name: "L  (1 x 0.5%)", v: 0.5 },
  { name: "d  (2 x 1.5%)", v: 3.0 },
  { name: "e  (1 x 3.0%)", v: 3.0 }
];
var i, sq = 0;
for (i = 0; i < parts.length; i++) sq += parts[i].v * parts[i].v;
var total = Math.sqrt(sq);

var left = 110;
var barW = W - left - 70;
var top = 26;
var rowH = (H - top - 52) / 5;
var scale = barW / 5.0;

ctx.fillStyle = C.ink;
ctx.fillText("Error budget for Y = 4FL / (pi d^2 e)", 12, 16);

for (i = 0; i < parts.length; i++) {
  var y = top + rowH * i + 14;
  ctx.fillStyle = C.figure;
  ctx.fillText(parts[i].name, 12, y + 4);
  ctx.fillStyle = C.rule;
  ctx.fillRect(left, y - 8, parts[i].v * scale, 13);
  ctx.fillStyle = C.figure;
  ctx.fillText(parts[i].v.toFixed(1) + "%", left + parts[i].v * scale + 6, y + 4);
}

var yt = top + rowH * 4 + 20;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(12, yt - 12); ctx.lineTo(W - 12, yt - 12); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("total (quadrature)", 12, yt + 6);
ctx.fillStyle = C.accent;
ctx.fillRect(left, yt - 6, total * scale, 13);
ctx.fillStyle = C.ink;
ctx.fillText(total.toFixed(2) + "%", left + total * scale + 6, yt + 6);

ctx.fillStyle = C.figure;
ctx.fillText("The total is smaller than the plain sum, 7.5%. Only the two biggest terms matter.", 12, H - 10);

out.note = "d and e together supply " + ((9 + 9) / sq * 100).toFixed(0) + " percent of the variance";
